public int findLargestSubstring(List<String> strings) {
    int maxSize = 0;
    for (String str : strings) {
        String inverse = new StringBuilder(str).reverse().toString();
        if (strings.stream().anyMatch(s -> s.contains(str) || s.contains(inverse))) {
            maxSize = Math.max(maxSize, str.length());
        }
    }
    return maxSize;
}

public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    for (String str : strings) {
        Set<String> substrings = new HashSet<>();
        for (int i = 0; i < str.length(); i++) {
            for (int j = i + 1; j <= str.length(); j++) {
                substrings.add(str.substring(i, j));
                substrings.add(new StringBuilder(str.substring(i, j)).reverse().toString());
            }
        }
        for (String sub : substrings) {
            for (String s : strings) {
                if (s.contains(sub) || s.contains(new StringBuilder(sub).reverse().toString())) {
                    if (sub.length() > maxLength) {
                        maxLength = sub.length();
                    }
                    break;
                }
            }
        }
    }
    return maxLength;
}

