public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    List<Integer> graph[] = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] path : paths) {
        graph[path[0]].add(path[1]);
        graph[path[1]].add(path[0]);
    }
    boolean[] visited = new boolean[n];
    if (hasPath(graph, start[0], end[0], visited)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean hasPath(List<Integer> graph[], int start, int end, boolean[] visited) {
    if (start == end) {
        return true;
    }
    visited[start] = true;
    for (int neighbor : graph[start]) {
        if (!visited[neighbor]) {
            if (hasPath(graph, neighbor, end, visited)) {
                return true;
            }
        }
    }
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[paths.length];
    boolean result = canTravelFrom(start, end, paths, visited);
    return result ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelFrom(int[] current, int[] end, int[][] paths, boolean[] visited) {
    int currentIndex = findIndex(current, paths);
    if (currentIndex == -1) {
        return false;
    }
    if (Arrays.equals(current, end)) {
        return true;
    }
    visited[currentIndex] = true;
    for (int i = 0; i < paths.length; i++) {
        if (paths[i][0] == current[0] && paths[i][1] == current[1] && !visited[i]) {
            if (canTravelFrom(new int[]{paths[i][2], paths[i][3]}, end, paths, visited)) {
                return true;
            }
        }
        if (paths[i][2] == current[0] && paths[i][3] == current[1] && !visited[i]) {
            if (canTravelFrom(new int[]{paths[i][0], paths[i][1]}, end, paths, visited)) {
                return true;
            }
        }
    }
    visited[currentIndex] = false;
    return false;
}

private static int findIndex(int[] coordinates, int[][] paths) {
    for (int i = 0; i < paths.length; i++) {
        if ((paths[i][0] == coordinates[0] && paths[i][1] == coordinates[1]) ||
            (paths[i][2] == coordinates[0] && paths[i][3] == coordinates[1])) {
            return i;
        }
    }
    return -1;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n * n];
    boolean[][] maze = new boolean[n][n];

    // Initialize the maze based on the paths
    for (int[] path : paths) {
        int from = path[0];
        int to = path[1];
        int fromRow = from / n;
        int fromCol = from % n;
        int toRow = to / n;
        int toCol = to % n;
        maze[fromRow][fromCol] = true; // Assuming paths imply a direct connection
    }

    // Perform BFS to check if there is a path from start to end
    ArrayDeque<int[]> queue = new ArrayDeque<>();
    queue.offer(start);
    visited[start[0] * n + start[1]] = true;

    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int currentRow = current[0];
        int currentCol = current[1];

        if (currentRow == end[0] && currentCol == end[1]) {
            return "can be travelled";
        }

        for (int[] direction : directions) {
            int newRow = currentRow + direction[0];
            int newCol = currentCol + direction[1];

            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && maze[newRow][newCol] && !visited[newRow * n + newCol]) {
                queue.offer(new int[]{newRow, newCol});
                visited[newRow * n + newCol] = true;
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    return dfs(start[0], start[1], end[0], end[1], visited, paths) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int endX, int endY, boolean[][] visited, int[][] paths) {
    if (x < 0 || x >= paths.length || y < 0 || y >= paths[0].length || visited[x][y]) {
        return false;
    }
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;
    for (int[] path : paths[x][y]) {
        if (dfs(path[0], path[1], endX, endY, visited, paths)) {
            return true;
        }
    }
    visited[x][y] = false;
    return false;
}

public static String appx(String word1, String word2) {
    int common = 0;
    for (char c : word1.toCharArray()) {
        if (word2.indexOf(c) != -1) {
            common++;
        }
    }
    int sum = word1.length() + word2.length();
    return "appx(" + word1 + ", " + word2 + ") = " + common + "/" + sum;
}

public static String appx(String word1, String word2) {
    Set<Character> set1 = new HashSet<>();
    for (char c : word1.toCharArray()) {
        set1.add(c);
    }

    Set<Character> set2 = new HashSet<>();
    for (char c : word2.toCharArray()) {
        set2.add(c);
    }

    int commonCount = 0;
    for (char c : set1) {
        if (set2.contains(c)) {
            commonCount++;
        }
    }

    int numerator = commonCount * 2;
    int denominator = word1.length() + word2.length();

    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

