public static String appx(String word1, String word2) {
    Set<Character> set1 = new HashSet<>();
    Set<Character> set2 = new HashSet<>();

    for (char c : word1.toCharArray()) {
        set1.add(c);
    }

    for (char c : word2.toCharArray()) {
        set2.add(c);
    }

    set1.retainAll(set2);
    int commonLetters = set1.size();
    int totalLetters = word1.length() + word2.length();

    int gcd = 1;
    for (int i = 1; i <= commonLetters && i <= totalLetters; i++) {
        if (commonLetters % i == 0 && totalLetters % i == 0) {
            gcd = i;
        }
    }

    return "appx(" + word1 + ", " + word2 + ") = " + (commonLetters / gcd) + "/" + (totalLetters / gcd);
}

public static String appx(String word1, String word2) {
    int common = 0;
    int total = word1.length() + word2.length();
    Set<Character> chars1 = new HashSet<>();
    Set<Character> chars2 = new HashSet<>();

    for (char c : word1.toCharArray()) {
        chars1.add(c);
    }

    for (char c : word2.toCharArray()) {
        if (chars1.contains(c)) {
            common++;
        }
        chars2.add(c);
    }

    total = chars1.size() + chars2.size() - common;
    int gcd = gcd(common, total);

    return String.format("appx(%s, %s) = %d/%d", word1, word2, common / gcd, total / gcd);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

public static String convertDatesToWeekdays(String date) {
    String[] dateParts = date.split(" ");
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);

    LocalDate localDate = LocalDate.of(year, month, day);
    String weekday = localDate.getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.getDefault());

    return date + " is a " + weekday;
}

