public int[] twoSum(int[] nums, int target) {
    // Create a HashMap to store the values and their indices
    HashMap<Integer, Integer> map = new HashMap<>();

    // Iterate through the array
    for (int i = 0; i < nums.length; i++) {
        // Calculate the complement that would add up to the target
        int complement = target - nums[i];

        // Check if the complement exists in the map
        if (map.containsKey(complement)) {
            // If it exists, return the indices of the complement and the current element
            return new int[] { map.get(complement), i };
        }

        // If not, put the current element and its index in the map
        map.put(nums[i], i);
    }

    // If no solution is found, throw an exception
    throw new IllegalArgumentException("No two sum solution");
}

public int[] twoSum(int[] nums, int target) {
    for (int i = 0; i < nums.length; i++) {
        for (int j = i + 1; j < nums.length; j++) {
            if (nums[i] + nums[j] == target) {
                return new int[]{i, j};
            }
        }
    }
    return new int[]{-1, -1};
}

