public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        adj.get(edge[0]).add(edge[1]);
        adj.get(edge[1]).add(edge[0]);
    }
    return dfs(0, -1, adj, hasApple) * 2;
}

private int dfs(int node, int parent, List<List<Integer>> adj, boolean[] hasApple) {
    int time = 0;
    for (int nei : adj.get(node)) {
        if (nei == parent) continue;
        time += dfs(nei, node, adj, hasApple);
    }
    if ((time > 0 || hasApple[node]) && node != 0) {
        return time + 1;
    }
    return 0;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    ArrayList<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] edge : edges) {
        graph[edge[0]].add(edge[1]);
        graph[edge[1]].add(edge[0]);
    }
    return dfs(0, -1, graph, hasApple) * 2;
}

private int dfs(int node, int parent, ArrayList<Integer>[] graph, boolean[] hasApple) {
    int time = 0;
    for (int neighbor : graph[node]) {
        if (neighbor == parent) continue;
        time += dfs(neighbor, node, graph, hasApple);
    }
    if ((time > 0 || hasApple[node]) && node != 0) time += 2;
    return time;
}

