    List<Integer>[] adj = new List[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        adj[edge[0]].add(edge[1]);
        adj[edge[1]].add(edge[0]);
    }
    boolean[] visited = new boolean[n];
    return dfs(0, adj, hasApple, visited) * 2;
}

private int dfs(int node, List<Integer>[] adj, boolean[] hasApple, boolean[] visited) {
    if (visited[node]) {
        return 0;
    }
    visited[node] = true;
    int time = 0;
    for (int neighbor : adj[node]) {
        time += dfs(neighbor, adj, hasApple, visited);
    }
    if (time > 0 || hasApple[node]) {
        return time + 1;
    }
    return 0;
}

public String sortString(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    while (s.length() > 0) {
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }
    }

    return result.toString();
}

