            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        // Step 1 to 3: Pick smallest characters
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }

        // Step 4 to 6: Pick largest characters
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            if (helper(nums, i, sum * i / n, 0, 0)) {
                return true;
            }
        }
    }
    return false;
}

private boolean helper(int[] nums, int targetSize, int targetSum, int index, int currentSum) {
    if (targetSize == 0 && targetSum == 0) {
        return true;
    }
    if (targetSize == 0 || targetSum == 0 || index >= nums.length) {
        return false;
    }
    return helper(nums, targetSize - 1, targetSum - nums[index], index + 1, currentSum + nums[index]) ||
           helper(nums, targetSize, targetSum, index + 1, currentSum);
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    for (int i = 0; i < (1 << n); i++) {
        int subsetSum = 0, subsetSize = 0;
        for (int j = 0; j < n; j++) {
            if ((i & (1 << j)) > 0) {
                subsetSum += nums[j];
                subsetSize++;
            }
        }
        if (subsetSize > 0 && subsetSize < n && (sum * subsetSize) % n == 0 && subsetSum == (sum * subsetSize) / n) {
            return true;
        }
    }
    return false;
}

