private boolean helper(int[] nums, int k, int target, int start, int count) {
    if (count == k && target == 0) {
        return true;
    }
    if (count == k || target == 0 || start >= nums.length) {
        return false;
    }
    for (int i = start; i < nums.length; i++) {
        if (helper(nums, k, target - nums[i], i + 1, count + 1)) {
            return true;
        }
    }
    return false;
}

