private boolean dfs(int[] nums, int targetSize, int start, int targetSum, int currentSum) {
    if (targetSize == 0) return currentSum == targetSum;
    if (start == nums.length) return false;

    return dfs(nums, targetSize - 1, start + 1, targetSum, currentSum + nums[start]) || 
           dfs(nums, targetSize, start + 1, targetSum, currentSum);
}

