public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance += 1;
        } else {
            balance -= 1;
            if (i < s.length() - 1 && s.charAt(i + 1) == ')') {
                i += 1;
            } else {
                insertions += 1;
            }
        }
        if (balance < 0) {
            insertions += 1;
            balance += 1;
        }
    }

    return insertions + balance * 2;
}

public int minInsertions(String s) {
    int left = 0;
    int right = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            if (right % 2 != 0) {
                insertions++;
                right--;
            }
            left++;
        } else {
            right++;
            if (left == 0) {
                insertions++;
            } else {
                left--;
            }
        }
    }

    return insertions + left * 2 + right * 2 - (left % 2 == 0 ? 0 : 2);
}

