public int findMinFibonacciNumbers(int k) {
    List<Integer> fib = new ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (fib.get(fib.size() - 1) < k) {
        fib.add(fib.get(fib.size() - 1) + fib.get(fib.size() - 2));
    }
    int count = 0;
    for (int i = fib.size() - 1; i >= 0; i--) {
        if (k >= fib.get(i)) {
            k -= fib.get(i);
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibList = generateFibonacci(k);
    return minFibonacciSum(fibList, k, 0);
}

private List<Integer> generateFibonacci(int k) {
    List<Integer> fibList = new ArrayList<>();
    int a = 1, b = 1;
    fibList.add(a);
    while (b <= k) {
        fibList.add(b);
        int temp = b;
        b = a + b;
        a = temp;
    }
    return fibList;
}

private int minFibonacciSum(List<Integer> fibList, int k, int count) {
    if (k == 0) return count;
    int index = fibList.size() - 1;
    while (fibList.get(index) > k) index--;
    return minFibonacciSum(fibList, k - fibList.get(index), count + 1);
}

