public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a');
    k -= n;
    for (int i = n - 1; k > 0; i--) {
        int add = Math.min(k, 25);
        result[i] += add;
        k -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    int pos = n - 1;
    k -= n;

    while (k > 0) {
        int add = Math.min(25, k);
        result[pos] = (char) ('a' + add);
        k -= add;
        pos--;
    }

    for (int i = 0; i <= pos; i++) {
        result[i] = 'a';
    }

    return new String(result);
}

