public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) return result;
        if (low <= 0) {
            result.add(0);
        }
        LinkedList<Integer> queue = new LinkedList<>();
        for (int i = 1; i <= 9; i++) {
            queue.offer(i);
        }
        while (!queue.isEmpty()) {
            int current = queue.poll();
            if (current > high) break;
            if (current >= low) {
                result.add(current);
            }
            int lastDigit = current % 10;
            if (lastDigit > 0) {
                queue.offer(current * 10 + lastDigit - 1);
            }
            if (lastDigit < 9) {
                queue.offer(current * 10 + lastDigit + 1);
            }
        }
        return result;
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    LinkedList<Integer> queue = new LinkedList<>();

    for (int i = 0; i <= 9; i++) {
        queue.add(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num >= low && num <= high) {
            result.add(num);
        }
        if (num == 0 || num > high) {
            continue;
        }
        int lastDigit = num % 10;
        if (lastDigit > 0) {
            queue.add(num * 10 + lastDigit - 1);
        }
        if (lastDigit < 9) {
            queue.add(num * 10 + lastDigit + 1);
        }
    }

    result.sort(null);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) {
            return result;
        }
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < 10; i++) {
            if (i >= low) {
                result.add(i);
            }
            if (i == 0 || i == 9) {
                continue;
            }
            queue.offer(i);
        }
        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num > high) {
                break;
            }
            int lastDigit = num % 10;
            if (lastDigit + 1 < 10) {
                int next = num * 10 + (lastDigit + 1);
                if (next >= low) {
                    result.add(next);
                }
                queue.offer(next);
            }
            if (lastDigit - 1 >= 0) {
                int next = num * 10 + (lastDigit - 1);
                if (next >= low) {
                    result.add(next);
                }
                queue.offer(next);
            }
        }
        result.sort(Integer::compareTo);
        return result;
    }

