private static void findSteppingNumbersHelper(int low, int high, int current, List<Integer> result) {
        if (current > high) {
            return;
        }

        if (current >= low) {
            result.add(current);
        }

        int lastDigit = current % 10;

        if (lastDigit > 0) {
            findSteppingNumbersHelper(low, high, current * 10 + (lastDigit - 1), result);
        }

        if (lastDigit < 9) {
            findSteppingNumbersHelper(low, high, current * 10 + (lastDigit + 1), result);
        }
    }

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lowerNumbers = n - (n / factor) * factor;
        long currentDigit = (n / factor) % 10;
        long higherNumbers = n / (factor * 10);

        if (currentDigit == 0) {
            count += higherNumbers * factor;
        } else if (currentDigit == 1) {
            count += higherNumbers * factor + lowerNumbers + 1;
        } else {
            count += (higherNumbers + 1) * factor;
        }
    }

    return count;
}

