private static boolean isPerfectSquare(int num) {
        int sqrt = (int) Math.sqrt(num);
        return sqrt * sqrt == num;
    }

private static void permute(int[] A, boolean[] visited, int start, int count) {
        if (start == A.length - 1) {
            count++;
            return;
        }

        for (int i = start; i < A.length; i++) {
            if (!visited[i]) {
                visited[i] = true;
                if (start == 0 || isPerfectSquare(A[start - 1] + A[i])) {
                    permute(A, visited, start + 1, count);
                }
                visited[i] = false;
            }
        }
    }

public static int squarePermutations(int[] A) {
    return backtrack(A, new boolean[A.length], 0);
}

private static int backtrack(int[] A, boolean[] used, int start) {
    if (start == A.length) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (start > 0 && !isPerfectSquare(A[start - 1] + A[i]))) {
            continue;
        }
        used[i] = true;
        count += backtrack(A, used, start + 1);
        used[i] = false;
    }

    return count;
}

