private static int backtrack(int[] A, int index) {
    if (index == A.length - 1) {
        return 1;
    }
    int count = 0;
    for (int i = index + 1; i < A.length; i++) {
        if (isPerfectSquare(A[index] + A[i])) {
            int temp = A[index];
            A[index] = A[i];
            A[i] = temp;
            count += backtrack(A, index + 1);
            temp = A[index];
            A[index] = A[i];
            A[i] = temp;
        }
    }
    return count;
}

