private static int countPermutations(int[] A, int start, boolean[] used) {
    if (start == A.length - 1) return 1;
    int count = 0;
    for (int i = start + 1; i < A.length; i++) {
        if (!used[i] && isPerfectSquare(A[start] + A[i])) {
            used[i] = true;
            count += countPermutations(A, start + 1, used);
            used[i] = false;
        }
    }
    return count;
}

