private static int dfs(int[] A, boolean[] used, int pos, int prev) {
    if (pos == A.length) return 1;
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!used[i] && isPerfectSquare(prev + A[i])) {
            used[i] = true;
            count += dfs(A, used, pos + 1, A[i]);
            used[i] = false;
        }
    }
    return count;
}

