public static List<String> centerSymmetricNumbers(int n) {
    if (n == 0) return Collections.singletonList("");
    if (n == 1) return Arrays.asList("0", "1", "8");
    return helper(n, n);
}

private static List<String> helper(int n, int m) {
    if (n == 0) return Collections.singletonList("");
    if (n == 1) return Arrays.asList("0", "1", "8");
    List<String> list = helper(n - 2, m);
    List<String> res = new ArrayList<>();
    for (String s : list) {
        if (n != m) res.add("0" + s + "0");
        res.add("1" + s + "1");
        res.add("6" + s + "9");
        res.add("8" + s + "8");
        res.add("9" + s + "6");
    }
    return res;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n == 0) return result;
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    helper(result, new char[n], 0, n - 1);
    return result;
}

private static void helper(List<String> result, char[] current, int left, int right) {
    if (left > right) {
        result.add(new String(current));
        return;
    }
    if (left == right) {
        current[left] = '0';
        result.add(new String(current));
        current[left] = '1';
        result.add(new String(current));
        current[left] = '8';
        return;
    }
    char[] symPairs = {'0', '1', '6', '8', '9'};
    for (char c : symPairs) {
        if (left == 0 && c == '0') continue; // Avoid leading zero for n > 1
        current[left] = c;
        current[right] = getSymmetric(c);
        helper(result, current, left + 1, right - 1);
    }
}

private static char getSymmetric(char c) {
    if (c == '6') return '9';
    if (c == '9') return '6';
    return c;
}

public static List<String> centerSymmetricNumbers(int n) {
        if (n <= 0) return new ArrayList<>();
        if (n == 1) return new ArrayList<>(List.of("0", "1", "8"));

        List<String> result = new ArrayList<>();
        helper(result, new char[n], 0, n - 1);
        return result;
    }

private static void helper(List<String> result, char[] current, int left, int right) {
        if (left > right) {
            result.add(new String(current));
            return;
        }
        if (left == right) {
            for (char c : "018".toCharArray()) {
                current[left] = c;
                result.add(new String(current));
            }
            return;
        }
        if (left > 0) {
            for (char c : "1689".toCharArray()) {
                current[left] = c;
                current[right] = getSymmetric(c);
                helper(result, current, left + 1, right - 1);
            }
        }
    }

private static char getSymmetric(char c) {
        switch (c) {
            case '1': return '1';
            case '6': return '9';
            case '8': return '8';
            case '9': return '6';
            default: return '0';
        }
    }

public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        helper(n, n, new char[n], result);
        return result;
    }

private static void helper(int n, int m, char[] arr, List<String> result) {
        if (n == 0) {
            result.add(new String(arr));
            return;
        }
        if (n == 1) {
            arr[m - 1] = '0';
            result.add(new String(arr));
            arr[m - 1] = '1';
            result.add(new String(arr));
            arr[m - 1] = '8';
            result.add(new String(arr));
            return;
        }
        char[] choices = {'0', '1', '6', '8', '9'};
        for (char c : choices) {
            if (n == m && c == '0') continue;
            arr[m - n - 1] = c;
            arr[m + n - 1] = getMirror(c);
            helper(n - 2, m, arr, result);
        }
    }

private static char getMirror(char c) {
        switch (c) {
            case '6': return '9';
            case '9': return '6';
            default: return c;
        }
    }

public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        helper(result, "", n, 0);
        helper(result, "0", n, 0);
        return result;
    }

private static void helper(List<String> result, String s, int n, int index) {
        if (index == n / 2) {
            if (n % 2 == 0 || s.charAt(0) != '0') {
                result.add(s + new StringBuilder(s).reverse().toString());
            }
            return;
        }
        for (char c : new char[]{'0', '1', '6', '8', '9'}) {
            if (index == 0 && c == '0' && n != 1) continue;
            helper(result, s + c, n, index + 1);
            if (c == '6') helper(result, s + '9', n, index + 1);
            else if (c == '9') helper(result, s + '6', n, index + 1);
        }
    }

