public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    boolean[] seen = new boolean[201]; // Assuming the range of nums is -100 to 100
    for (int num : nums) {
        if (!seen[num + 100]) { // Adjusting index to handle negative numbers
            sum += num;
            seen[num + 100] = true;
        }
    }
    return sum;
}

