    Set<Integer> uniqueElements = new HashSet<>();
    for (int num : nums) {
        uniqueElements.add(num);
    }
    int sum = 0;
    for (int num : uniqueElements) {
        sum += num;
    }
    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    Map<Integer, Integer> frequencyMap = new HashMap<>();
    for (int num : nums) {
        frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    boolean[] seen = new boolean[2001]; // Assuming the range of nums is [-1000, 1000]

    for (int num : nums) {
        num += 1000; // Offset to use non-negative indices
        if (!seen[num]) {
            sum += num;
            seen[num] = true;
        } else if (seen[num] == 2) {
            sum -= num - 2000; // Remove the duplicate to correct the sum
            seen[num] = false;
        }
    }

    return sum - 1000 * nums.length; // Adjust for the offset
}

