        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Create an array to store the minimum number of perfect squares for each number up to n
    int[] dp = new int[n + 1];

    // Initialize the array with a large value (n+1 is the maximum possible)
    for (int i = 1; i <= n; i++) {
        dp[i] = i + 1;
    }

    // Base case: 0 can be represented by 0 perfect squares
    dp[0] = 0;

    // Iterate through each number up to n
    for (int i = 1; i <= n; i++) {
        // Check each perfect square less than or equal to i
        for (int j = 1; j * j <= i; j++) {
            // Update the dp array with the minimum number of perfect squares
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // Return the minimum number of perfect squares for n
    return dp[n];
}

